'use strict';
// Preview identity is deliberately memory-only. It is not an authenticated session.
let previewAccount=null;
if(!state.leaseMembers)state.leaseMembers=state.apartments.flatMap(a=>[{id:'member-'+a.id,apt:a.id,name:a.name,type:'Primary leaseholder'},...(a.id===1?[{id:'member-secondary-1',apt:1,name:'Sam Morgan',type:'Secondary leaseholder'},{id:'member-dependent-1',apt:1,name:'Casey Morgan',type:'Dependent'}]:[])]);
if(!state.accounts)state.accounts=state.apartments.map(a=>({id:'resident-'+a.id,memberId:'member-'+a.id,email:`resident${a.id}@example.invalid`,status:'Sample active'}));
const primaryMember=id=>state.leaseMembers.find(m=>m.apt===id&&m.type==='Primary leaseholder');
const accountApartment=account=>state.leaseMembers.find(m=>m.id===account.memberId)?.apt;
const oldRender=render,oldBind=bind,oldAction=action,oldAdminContent=adminContent;
function loginPage(){return `<main class="login-shell"><section class="login-story"><div class="brand"><div class="brandmark">${icon('leaf')}</div><div>Goo Resident<br><small>YOUR COMMUNITY, CONNECTED</small></div></div><div class="login-story-copy"><div class="eyebrow">A little closer to home</div><h1>Your home.<br>Your community.<br>One familiar place.</h1><p>From everyday essentials to moments that bring us together. Welcome to your resident portal.</p><div class="login-building" aria-hidden="true"><svg viewBox="0 0 440 180"><path d="M0 160Q110 100 220 155T440 140V180H0" fill="#365e48"/><circle cx="355" cy="35" r="26" fill="#d8e9ad"/><path d="M72 171V75l60-35 60 35v96M215 171V93l54-30 54 30v78" fill="#e3e7d0"/><path d="M72 75h120M215 93h108" stroke="#789275" stroke-width="3"/><g fill="#698365"><path d="M93 91h19v24H93zM151 91h19v24h-19zM123 137h20v34h-20zM233 109h18v22h-18zM287 109h18v22h-18zM260 146h19v25h-19z"/><ellipse cx="374" cy="125" rx="28" ry="38"/></g><path d="M374 130v50M39 130v50" stroke="#b6c79c" stroke-width="3"/><ellipse cx="39" cy="113" rx="20" ry="29" fill="#7c9a6b"/></svg></div></div><div class="login-story-footer">Thoughtfully connected. Comfortably home.</div></section><section class="login-entry"><div class="login-mobile-brand">Goo Resident</div><div class="login-form-wrap"><span class="tag">${esc(state.community)}</span><h1>Welcome home.</h1><p class="muted">Sign in to your resident account.</p><form id="login-form" aria-describedby="login-status"><fieldset disabled style="border:0;padding:0;margin:26px 0 0"><label>Email address<input type="email" name="email" autocomplete="username" placeholder="you@example.com"></label><label>Password<input type="password" name="password" autocomplete="current-password" placeholder="Enter your password"></label></fieldset><div class="login-help"><span>Office-provisioned access</span><button type="button" class="text-btn" data-action="recovery">Forgot password?</button></div><button class="btn primary login-submit" type="submit" disabled>Sign in</button></form><div class="hint" id="login-status"><b>Login preview · not connected yet</b><br>Email/password sign-in and recovery are awaiting a supported authentication service. Fields are disabled; no credentials are collected.</div><p class="login-invite">New here? Your community office creates an individual account for each resident listed on the lease. There is no public sign-up.</p><div class="preview-entry"><span class="eyebrow">Explore the sample community</span><button class="btn" data-action="preview-resident">Preview resident portal ${icon('arrow')}</button><button class="text-btn" data-action="preview-office">Preview office tools</button><small>Fictional data only. Preview access is not authentication.</small></div></div><footer>Goo Resident · Your home, connected.</footer></section></main>`}
render=function(){if(!previewAccount){document.querySelector('#app').innerHTML=loginPage();bind();return}oldRender();const right=document.querySelector('.topright');if(right){const label=document.createElement('span');label.className='preview-identity';label.textContent=previewAccount==='office'?'Office preview':`Preview: ${primaryMember(aptId)?.name||apt().name}`;right.prepend(label);const exit=document.createElement('button');exit.className='text-btn';exit.textContent='Exit preview';exit.onclick=()=>{previewAccount=null;role='resident';page='home';close();render();window.scrollTo(0,0)};right.append(exit)}if(role==='office'){const tabs=document.querySelector('.admin-tabs');const b=document.createElement('button');b.className='btn'+(adminTab==='accounts'?' active':'');b.textContent='Accounts & lease members';b.onclick=()=>{adminTab='accounts';render()};tabs.append(b)}};
adminContent=function(){if(adminTab!=='accounts')return oldAdminContent();return `<section class="card"><div class="card-head"><div><h2>Resident accounts & lease members</h2><p class="muted" style="font-size:12px;margin-top:7px">Individual accounts for primary, secondary and dependent lease members. Only the office provisions accounts; every account belongs to a recorded lease member.</p></div></div><div class="hint"><b>Office administrator preview · office@example.invalid.</b> All office controls are available in this explicit demo role; typing an office email does not grant privileges. All addresses must end in <code>@example.invalid</code>. Invitations are drafts, never sent. Only a connected identity service can issue activation links, manage passwords or create real accounts.</div><label>Find an apartment or primary leaseholder<input id="account-search" placeholder="Apartment number or name"></label><div class="table-wrap"><table><thead><tr><th>Apartment / block</th><th>Primary leaseholder</th><th>Primary account</th><th>Lease members</th><th>Manage</th></tr></thead><tbody>${state.apartments.map(a=>{const m=primaryMember(a.id),ac=state.accounts.find(c=>c.memberId===m?.id);return `<tr data-account-search="${esc((a.number+' '+a.name).toLowerCase())}"><td>${esc(a.number)} / ${a.block}</td><td>${esc(m?.name||a.name)}</td><td>${esc(ac?.email||'No invitation draft')}<br><small>${esc(ac?.status||'Not provisioned')}</small></td><td>${state.leaseMembers.filter(m=>m.apt===a.id).length}</td><td><button class="text-btn" data-manage-lease="${a.id}">Manage lease</button></td></tr>`}).join('')}</tbody></table></div></section>`};
let manageLease;
function editMember(aptId,memberId){const m=state.leaseMembers.find(m=>m.id===memberId);modal(m?'Edit lease member':'Add lease member',`<form id="member-form">${input('Sample full name','name',m?.name||'','text','maxlength="80"')}${select('Lease relationship','type',['Secondary leaseholder','Dependent'],m?.type)}<p class="hint">First record the lease member, then use Create account to prepare their individual account invitation. No shared household password.</p><button class="btn primary" type="submit">Save lease member</button></form>`);document.querySelector('#member-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(!data.name.trim()){toast('Enter a sample name.');return}if(m)Object.assign(m,data);else state.leaseMembers.push({...data,id:'member-'+Date.now(),apt:aptId});save();manageLease(aptId);toast('Lease member saved. The office can now create their individual account.')}}
action=function(a){if(a==='preview-resident'){const ac=state.accounts.find(c=>c.status==='Sample active');if(!ac){toast('No active sample account. Use the office preview to restore one.');return}previewAccount=ac.id;aptId=accountApartment(ac);role='resident';page='home';render();return}if(a==='preview-office'){previewAccount='office';role='office';adminTab='accounts';render();return}if(a==='recovery'){modal('Reset your password',`<p>Once secure sign-in is connected, residents can request a one-time password-reset link at their verified email address.</p><div class="hint" style="margin:18px 0">Password recovery is not active in this preview. No reset email has been requested or sent. Contact your community office if you need help with a real account.</div><button class="btn" data-action="close">Back to sign in</button>`);return}if(a==='role')previewAccount=role==='resident'?'office':(state.accounts.find(c=>accountApartment(c)===aptId)?.id||'resident-1');oldAction(a)};
bind=function(root=document){oldBind(root);root.querySelectorAll('[data-manage-lease]').forEach(b=>b.onclick=()=>manageLease(+b.dataset.manageLease));root.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{const ac=state.accounts.find(c=>accountApartment(c)===+b.dataset.preview);if(ac?.status!=='Sample active'){toast('This sample account is not active. Restore sample access in Accounts & lease members.');return}previewAccount=ac.id;aptId=+b.dataset.preview;role='resident';page='home';render();window.scrollTo(0,0)});const search=root.querySelector('#account-search');if(search)search.oninput=()=>root.querySelectorAll('[data-account-search]').forEach(r=>r.hidden=!r.dataset.accountSearch.includes(search.value.toLowerCase()));const login=root.querySelector('#login-form');if(login)login.onsubmit=e=>e.preventDefault()};
// Primary leaseholder names remain consistent across existing apartment editing and membership views.
const oldSave=save;save=function(){for(const a of state.apartments){const m=primaryMember(a.id);if(m)m.name=a.name}return oldSave()};
// All lease roles are eligible; accounts are separate from membership and created by office staff.
function provisionMember(memberId){const member=state.leaseMembers.find(m=>m.id===memberId);const account=state.accounts.find(c=>c.memberId===memberId);modal(`${account?'Manage':'Create'} individual account`,`<p><b>${esc(member.name)}</b><br>${esc(member.type)} · Apartment ${esc(state.apartments.find(a=>a.id===member.apt).number)}</p><form id="member-account-form" style="margin-top:18px"><label>Individual sample email<input name="email" type="email" value="${esc(account?.email||'')}" placeholder="person@example.invalid" required pattern="[^@]+@example\.invalid"></label><div class="hint">Office-provisioned account for this lease member only. In production, the authentication service delivers a private activation link so this person sets their own password. No shared or plaintext passwords.<br><b>Preview:</b> fictional addresses only; nothing is sent.</div><button class="btn primary" type="submit">Save account invitation draft</button></form>${account?`<p style="margin-top:15px;font-size:12px">Status: ${esc(account.status)}</p><div class="actions"><button class="text-btn" id="member-access">${account.status==='Sample active'?'Disable sample access':'Enable sample preview'}</button></div>`:''}`);document.querySelector('#member-account-form').onsubmit=e=>{e.preventDefault();const email=new FormData(e.target).get('email').trim().toLowerCase();if(!/^[^@\s]+@example\.invalid$/.test(email)){toast('Use a fictional @example.invalid address.');return}if(state.accounts.some(c=>c.email===email&&c.memberId!==memberId)){toast('Each person must have a different account email.');return}if(account)Object.assign(account,{email,status:'Invitation draft'});else state.accounts.push({id:'account-'+Date.now(),memberId,email,status:'Invitation draft'});save();manageLease(member.apt);toast('Individual account draft saved. No invitation was sent.')};const toggle=document.querySelector('#member-access');if(toggle)toggle.onclick=()=>{account.status=account.status==='Sample active'?'Disabled preview':'Sample active';save();manageLease(member.apt);toast('Sample access updated. This does not activate a real account.')}}
manageLease=function(id){const a=state.apartments.find(a=>a.id===id);modal(`Apartment ${esc(a.number)} · Lease members`,`<p class="muted" style="font-size:12px;margin-bottom:16px">Every account belongs to one recorded lease member. Primary, secondary and dependent residents use separate credentials to access this same apartment.</p><div class="lease-members">${state.leaseMembers.filter(m=>m.apt===id).map(m=>{const ac=state.accounts.find(c=>c.memberId===m.id);return `<div class="notice"><b>${esc(m.name)}</b><br><small>${esc(m.type)}</small><p style="font-size:12px">${esc(ac?.email||'Account not provisioned')}<br>${esc(ac?.status||'Office must create account')}</p><button class="text-btn" data-member-account="${m.id}">${ac?'Manage account':'Create account'}</button>${m.type!=='Primary leaseholder'?`<button class="text-btn" data-edit-member="${m.id}">Edit member</button>`:''}</div>`}).join('')}</div><button class="btn" id="add-member" style="margin-top:15px">+ Add lease member</button><div class="hint" style="margin-top:20px">Sample workflow only. Account creation and activation will require an authenticated staff user and a connected identity service. No emails are sent or passwords created here.</div>`);document.querySelector('#add-member').onclick=()=>editMember(id);document.querySelectorAll('[data-member-account]').forEach(b=>b.onclick=()=>provisionMember(b.dataset.memberAccount));document.querySelectorAll('[data-edit-member]').forEach(b=>b.onclick=()=>editMember(id,b.dataset.editMember))};
const accountAction=action;
action=function(a){if(a==='preview-resident'){const active=state.accounts.filter(c=>c.status==='Sample active');modal('Choose a fictional resident',`<p class="hint">Preview individual accounts linked to shared apartments. This selector is a demo tool, not a sign-in method.</p><label>Sample resident<select id="sample-person">${active.map(c=>{const m=state.leaseMembers.find(m=>m.id===c.memberId);const ap=state.apartments.find(a=>a.id===m.apt);return `<option value="${c.id}">${esc(m.name)} · ${esc(m.type)} · Apt ${esc(ap.number)}</option>`}).join('')}</select></label><button class="btn primary" id="open-person" ${active.length?'':'disabled'}>Open resident preview</button>`);document.querySelector('#open-person').onclick=()=>{const ac=active.find(c=>c.id===document.querySelector('#sample-person').value);if(!ac)return;previewAccount=ac.id;aptId=accountApartment(ac);role='resident';page='home';close();render()};return}accountAction(a)};
// Initial sample household demonstrates independent accounts for all three lease roles.
if(!state.individualAccountsVersion){for(const m of state.leaseMembers.filter(m=>m.apt===1&&m.type!=='Primary leaseholder'))if(!state.accounts.some(c=>c.memberId===m.id))state.accounts.push({id:'account-'+m.id,memberId:m.id,email:m.type==='Dependent'?'casey@example.invalid':'sam@example.invalid',status:'Sample active'});state.individualAccountsVersion=1}
const accountRender=render;
render=function(){accountRender();if(previewAccount&&previewAccount!=='office'){const ac=state.accounts.find(c=>c.id===previewAccount);const m=state.leaseMembers.find(m=>m.id===ac?.memberId);const label=document.querySelector('.preview-identity');if(label&&m)label.textContent=`Preview: ${m.name} · ${m.type}`}};
render();


